import{_ as o,o as e,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Destacar a parte do prazo em foco","description":"","frontmatter":{"title":"Destacar a parte do prazo em foco","id":"eproc-destacar-parte-prazo","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.9.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-destacar-parte-prazo.md","filePath":"funcionalidades/eproc-destacar-parte-prazo.md"}'),s={name:"funcionalidades/eproc-destacar-parte-prazo.md"};function i(d,a,n,p,c,l){return e(),r("div",null,a[0]||(a[0]=[t('<h1 id="destacar-a-parte-do-prazo-em-foco" tabindex="-1">Destacar a parte do prazo em foco <a class="header-anchor" href="#destacar-a-parte-do-prazo-em-foco" aria-label="Permalink to &quot;Destacar a parte do prazo em foco&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na seleção das partes a intimar, os campos de prazo ficam numa coluna longe dos nomes das partes e dos polos. Quando você clica num campo de prazo, de data final ou de intimação urgente, a linha inteira ganha um fundo cinza discreto e o nome da parte ou do polo ganha um contorno, também cinza. Assim você sabe para quem é o prazo que está digitando.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, na escolha das partes a intimar:</p><ul><li>na tela de intimação do processo;</li><li>no &quot;Intimar/Citar&quot; do cadastro e da edição de minuta.</li></ul><p>Funciona nos dois modos das opções avançadas, &quot;Por Tipo de Parte&quot; e &quot;Por Pólo&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a intimação de um processo (ou marque &quot;Intimar/Citar&quot; numa minuta).</li><li>Em &quot;Opções Avançadas&quot;, escolha &quot;Por Pólo&quot; ou &quot;Por Tipo de Parte&quot;.</li><li>Clique no campo de prazo de uma linha, ou chegue a ele com Tab. A linha e o nome da parte ou do polo ficam destacados.</li><li>Ao sair do campo, o destaque some.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><p>O destaque só marca a linha. Os prazos e as partes marcadas não mudam.</p>',13)]))}const h=o(s,[["render",i]]);export{m as __pageData,h as default};
